window.VO = [{"id":"s01","text":"Mosquitoes love some people a hundred times more than others.","at":0.9,"t0":0.45,"t1":3.885},{"id":"s02","text":"If that's you, it isn't your sweet blood.","at":8.47,"t0":4.235,"t1":6.495},{"id":"s03","text":"They pick you before they've tasted a drop.","at":13.99,"t0":6.995,"t1":9.2},{"id":"s04","text":"They follow your breath from ten meters away, then your heat.","at":19.5,"t0":9.75,"t1":12.935},{"id":"s05","text":"But everyone breathes, and everyone's warm. So why you?","at":26.67,"t0":13.335,"t1":16.605},{"id":"s06","text":"In a New York lab, sixty-four people wore nylon stockings on their arms.","at":34.41,"t0":17.205,"t1":21.58},{"id":"s07","text":"Then dengue mosquitoes chose between them, two at a time.","at":44.06,"t0":22.03,"t1":25.38},{"id":"s08","text":"One volunteer kept winning. Subject thirty-three.","at":51.76,"t0":25.88,"t1":29.05},{"id":"s09","text":"A hundred times more attractive than last place.","at":59,"t0":29.5,"t1":32.125},{"id":"s10","text":"Their skin made far more of certain acids, and mosquitoes follow that smell.","at":65.35,"t0":32.675,"t1":36.8},{"id":"s11","text":"Even mosquitoes with a damaged sense of smell still found them.","at":74.6,"t0":37.3,"t1":40.69},{"id":"s12","text":"And three years later, the magnets were still magnets.","at":82.38,"t0":41.19,"t1":44.225},{"id":"s13","text":"So if they always pick you, they'll pick you next year too.","at":89.45,"t0":44.725,"t1":47.74}];
